sys_script.script:
(function executeRule(current, previous /*null when async, previous is the record before this change*/) {

    // Guard: nothing to link without a caller
    if (!current.caller_id) {
        return;
    }

    // ITSM/CMDB: link the caller's computer CI
    var ci = new GlideRecord('cmdb_ci_computer'); // Creates GlideRecord on cmdb ci computer table
    ci.addQuery('assigned_to', current.caller_id); // add query to GlideRecord
    ci.setLimit(1); // Only return one computer
    ci.query(); // Run the query
	// ci.next moves to the first matching record, if it exists.
    if (ci.next()) {
        current.cmdb_ci = ci.getUniqueValue(); // sets current incident's cmdb ci to the computer if found
    }

    // ITSM routing: send hardware incidents to the Hardware group
    var isHardware = (current.category == 'hardware') ||
                     /laptop|computer|monitor|keyboard|printer/i.test(current.short_description + ''); // checks if cat is already hardware, or the description contains common hardware words. i makes it case insensitive
    if (isHardware) {
        var grp = new GlideRecord('sys_user_group'); // create new GlideRecord for group
        grp.addQuery('name', 'Hardware'); // add query for hardware group
        grp.setLimit(1); // return only one
        grp.query();
        if (grp.next()) {
            current.assignment_group = grp.getUniqueValue();
        }
    }

})(current, previous);
